VID.narration = {"look":{"bar":false},"scenes":[{"dur":9.288,"caps":[[0.5,7.31,"Phase six. Error detection and correction. This is how data survives a noisy wire."]],"warp":[[0,0],[0.5,0.9],[9.288,4]]},{"dur":18.344,"caps":[[0.5,5.07,"A message travels as bits."],[5.32,9.65,"Noise on the wire flips a bit."],[9.9,14.07,"The receiver cannot tell."],[14.32,16.89,"Fix: add a check bit."]],"warp":[[0,0],[0.5,0.5],[5.32,3.5],[9.9,6],[14.32,8.7],[18.344,10.5]]},{"dur":23.336,"caps":[[0.61,3.9,"Count the 1s in the message."],[4.14,8.31,"Add a bit that makes the total even."],[8.56,12.49,"One flip makes the total odd: caught."],[12.74,17.55,"But which bit? Parity cannot say."],[17.8,21.66,"Two flips make it even again: missed."]],"warp":[[0,0],[0.605,1.1],[4.145,3.1],[8.565,6.1],[12.745,8.2],[17.805,10.7],[23.336,12.5]]},{"dur":23.429,"caps":[[0.66,4.59,"The CRC: a pattern both sides know."],[4.84,9.89,"Add one zero per check bit, then divide."],[10.14,13.51,"Line the pattern up under the next 1."],[13.76,18.09,"Too short to divide: that is the remainder."],[18.34,22.11,"Send the message plus the remainder."]],"warp":[[0,0],[0.66,1.2],[4.84,3.3],[10.14,5.6],[13.76,7.7],[18.34,9.9],[23.429,12]]},{"dur":26.796,"caps":[[0.66,4.35,"Divide the frame by the same pattern."],[4.6,10.85,"A clean frame divides exactly: 000."],[11.1,16.47,"These two flips change the remainder."],[16.72,21.05,"A burst of three is caught too."],[21.3,25.63,"More check bits catch longer bursts."]],"warp":[[0,0],[0.66,1.2],[4.6,4.5],[11.1,7.1],[16.72,10.2],[21.3,12.6],[26.796,13.9]]},{"dur":23.103,"caps":[[0.5,5.55,"A download checks every frame."],[5.8,10.53,"Check fails, so ask for a resend."],[10.78,16.15,"A probe is minutes away."],[16.4,21.85,"Too slow, so it repairs itself."]],"warp":[[0,0],[0.5,0.4],[5.8,2.9],[10.78,6.4],[16.4,9.5],[23.103,11.5]]},{"dur":34.993,"caps":[[1.16,5.17,"One flip is one step."],[5.42,10.07,"Only 000 and 111 are valid words."],[10.32,16.33,"Three steps apart: distance 3."],[16.58,23.07,"Nearest valid word is 000: fixed."],[23.32,30.13,"Two flips lead to the wrong word."],[30.38,33.67,"Repeating works but wastes bits."]],"warp":[[0,0],[1.155,2.1],[5.415,3.95],[10.315,6.1],[16.575,9.6],[23.315,12.1],[30.375,13.9],[34.993,15.2]]},{"dur":35.062,"caps":[[0.5,4.19,"Hamming sends 4 useful bits in 7."],[4.44,8.37,"Check bits sit at positions 1, 2, 4."],[8.62,11.19,"Write each position in binary."],[11.44,15.05,"p4 guards positions starting with 1."],[15.3,18.59,"Its bit makes the 1s even."],[18.84,23.33,"p2 guards positions with a middle 1."],[23.58,29.43,"p1 guards positions ending in 1."],[29.68,32.89,"Every group now has an even count."]],"warp":[[0,0],[0.5,0.9],[4.44,2.8],[8.62,4.6],[11.44,6.2],[15.3,7.7],[18.84,9.3],[23.58,11.3],[29.68,13.45],[35.062,14.95]]},{"dur":28.282,"caps":[[0.5,5.15,"A clean word passes all three checks."],[5.4,8.53,"Noise flips position 6."],[8.78,13.27,"Recount each group: odd means failed."],[13.52,17.37,"p4 and p2 fail; p1 passes."],[17.62,22.35,"Failures read as binary: 110 is 6."],[22.6,26.37,"Flip position 6 back: fixed."]],"warp":[[0,0],[0.5,0.7],[5.4,3.3],[8.78,5],[13.52,8.8],[17.62,10.6],[22.6,12.3],[28.282,14]]},{"dur":28.746,"caps":[[1.21,6.34,"Two bits flip: positions 2 and 5."],[6.59,10.92,"All fail: 111 means position 7."],[11.17,16.62,"The repair flips an innocent bit."],[16.87,20.16,"Checks pass, yet the data is wrong."],[20.41,27.3,"Hamming fixes exactly one error."]],"warp":[[0,0],[1.21,2.2],[6.59,5.5],[11.17,7.6],[16.87,9.1],[20.41,10.8],[28.746,12.2]]},{"dur":13.328,"caps":[],"warp":[[0,0],[0.5,0.9],[4.92,2],[8.94,3.1],[13.328,9]]}]};
